const csvD=NS.Telemetry.prototype.snapshotsCSV;
NS.Telemetry.prototype.snapshotsCSV=function(){const base=csvD.call(this),lines=base.split('\n');if(!lines.length)return base;const G=['multiWarNations33D','coalitionWars33D','maxConcurrentWarsNation33D','interventions33D','independentConcurrentDeclarations33D','activeEngagements33D','engagementRounds33D','fieldFormations33D','assignedFormations33D','constructionProgressTiles33D'],R=['activeWarCount33D','fieldFormationCount33D','assignedFormationCount33D','defenseMissions33D','offenseMissions33D'],q=v=>`"${String(v??'').replace(/"/g,'""')}"`;lines[0]+=','+[...G,...R].map(q).join(',');let i=1;for(const s of this.snapshots||[])for(const row of s.villages||[]){if(i>=lines.length)break;lines[i++]+=','+[...G.map(k=>s.global?.[k]),...R.map(k=>row?.[k])].map(q).join(',');}return lines.join('\n');};
const jsonD=NS.Telemetry.prototype.toJSON;
NS.Telemetry.prototype.toJSON=function(w){const d=jsonD.call(this,w);d.version='0.33D';Object.assign(d.worldSummary,{v33DRevision:REV33D,multiFrontWar33D:'one nation may participate in up to two simultaneous wars in D V1 (single constant, expandable later); wars carry sideAIds/sideBIds and support co-belligerent intervention',multiFormation33D:'Person-backed field manpower may split into multiple formations when manpower/front demand supports it; no synthetic soldiers',formationAssignment33D:'each field formation carries assignedWarId, assignedFrontId and mission',capitalDefense33D:'core threat can produce INTERCEPT / SCREEN / HOLD_CORE instead of unconditional core stacking',coalitionEngagement33D:'same-side formations from multiple nations reinforce one persistent engagement and fight through coalition side power',constructionProgress33D:'map renders actual construction/upgrade/land-development progress bars without changing build simulation',warPulseOwner33D:'V0.33D suppresses the inherited lexical V0.33 daily war pulse and runs exactly one D multi-front pulse per calendar day'});return d;};
