function dlD(name,text,type='application/json'){const blob=new Blob([text],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
const prevSaveD=NS.SaveSystem;(function(){const KEY='village-observer-v0-33d',fallback=['village-observer-v0-33c3f','village-observer-v0-33c3','village-observer-v0-33c2','village-observer-v0-33c1','village-observer-v0-33c','village-observer-v0-33b1','village-observer-v0-33b','village-observer-v0-33a','village-observer-v0-33','village-observer-v0-32f'];NS.SaveSystem={save(w){localStorage.setItem(KEY,JSON.stringify(w.serialize()));},load(){let r=localStorage.getItem(KEY);for(const k of fallback)if(!r)r=localStorage.getItem(k);return r?NS.World.from(JSON.parse(r)):null;},export(w){dlD(`village-observer-v033D-save-${w.year}y.json`,JSON.stringify(w.serialize()));},exportDevJSON(w){dlD(`village-observer-v033D-devlog-${w.telemetry.sessionId}.json`,JSON.stringify(w.telemetry.toJSON(w)));},exportDevCSV(w){const text=w.telemetry.snapshotsCSV(),c=NS.V032E14?.validateCSV?.(text);if(c&&!c.ok)throw new Error(`CSV schema mismatch: expected ${c.columns} columns; bad rows ${c.bad.slice(0,8).join(', ')}`);dlD(`village-observer-v033D-snapshots-${w.telemetry.sessionId}.csv`,'\ufeff'+text,'text/csv;charset=utf-8');},async import(file){return NS.World.from(JSON.parse(await file.text()));},async importMap(file){return attachD(await prevSaveD.importMap(file));},async importScenario(file){return attachD(await prevSaveD.importScenario(file));},exportScenario(w,meta=null){const x=NS.V032E14?.scenarioWrapper?.(w,meta);if(!x)return prevSaveD.exportScenario(w,meta);x.meta={...x.meta,intendedVersion:'0.33D'};x.world.testScenario={...x.meta};if(x.world.v32e11)x.world.v32e11.scenario={...x.meta};dlD(`village-observer-v033D-scenario-${x.meta.id}.json`,JSON.stringify(x));return x;}};})();
NS.V033.activeWars=activeWarsD;NS.V033.warForNation=warForNationD;NS.V033.declareWar=declareWarD;NS.V033.endWar=endWarD;NS.V033.summary=summaryNationD;NS.V033.occupy=occupyD;
if(NS.UI){const setD=NS.UI.prototype.setWorld,headD=NS.UI.prototype.renderHeader,contentD=NS.UI.prototype.renderVillageContent,mapD=NS.UI.prototype.renderMap,renderD=NS.UI.prototype.render;NS.UI.prototype.setWorld=function(w){return setD.call(this,attachD(w));};NS.UI.prototype.renderHeader=function(){headD.call(this);document.title='Village Observer V0.33D';const b=document.getElementById('versionBadge');if(b)b.innerHTML='Village Observer · <strong>V0.33D</strong>';const st=this.q?.('runtimeStatus');if(st){const wars=activeWarsD(this.world),multi=(this.world.activeVillages||[]).filter(v=>warsForNationD(this.world,v.id).length>=2).length;st.textContent=`✓ V0.33D 다중전선 · active wars ${wars.length} · 복수전쟁 국가 ${multi} · coalition ${wars.filter(x=>x.sideAIds.length>1||x.sideBIds.length>1).length}`;}updateWarBannerD(this);};NS.UI.prototype.renderVillageContent=function(){const r=contentD.call(this);const v=this.world?.selectedNation,root=this.q?.('villageContent');if(v&&root&&this.sub==='military'&&!NS.V033E3&&!root.querySelector('.v33d-panel'))root.insertAdjacentHTML('afterbegin',militaryPanelD(v,this.world));return r;};NS.UI.prototype.renderMap=function(){mapD.call(this);drawMultiFrontD(this);drawConstructionProgressD(this);};NS.UI.prototype.render=function(){const r=renderD.call(this);updateWarBannerD(this);return r;};}
if(typeof document!=='undefined'){const st=document.createElement('style');st.textContent=`.v33d-panel{margin:0 0 10px;padding:10px;border:1px solid rgba(160,130,255,.32);border-radius:12px;background:rgba(95,70,155,.07)}.v33d-forms{display:grid;gap:6px;margin-top:8px}.v33d-forms>div{padding:7px 8px;border-radius:8px;background:rgba(255,255,255,.04);font-size:11px}.v33d-banner-top,.v33d-banner-detail{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.v33d-banner-top select{max-width:min(62vw,520px);font-size:11px}.v33d-banner-detail{margin-top:5px}`;document.head.appendChild(st);}
if(Array.isArray(NS.PATCH_NOTES)&&!NS.PATCH_NOTES.some(x=>x.version==='V0.33D'))NS.PATCH_NOTES.unshift({version:'V0.33D',date:'2026-09-29',title:'Multi-front Warfare V1',summary:'C 계열에서 완성한 단일 Formation 전쟁을 국가 단위 다중전선 지휘로 확장합니다. 복수전쟁·공동교전국·복수 야전대·Formation별 임무·수도방어 태세와 건설 진행 표시를 추가합니다.',sections:[['다중전쟁·참전',['한 국가는 최대 2개의 독립 전쟁에 동시에 참여할 수 있습니다.','기존 전쟁에는 제3국이 A/B 어느 한쪽의 공동교전국으로 참전할 수 있으며 sideAIds/sideBIds로 저장합니다.','정식 동맹·call-to-arms는 아직 도입하지 않습니다.']],['복수 야전대·전선 배정',['실제 Person 현역을 기반으로 병력과 전선 수가 충분할 때 제2/제3야전대를 구성합니다. 가상 병력은 만들지 않습니다.','각 Formation은 assignedWarId / assignedFrontId / mission을 가지며 하루에 하나의 전쟁 이동만 수행합니다.']],['수도방어 태세',['수도 위협 시 무조건 전군 귀환하지 않고 전력비에 따라 INTERCEPT / SCREEN / HOLD_CORE를 선택합니다.','복수 Formation이면 한 부대가 수도방어를 맡는 동안 다른 부대는 공세·해방 임무를 유지할 수 있습니다.']],['Coalition Engagement',['같은 전쟁·같은 타일의 동측 Formation은 하나의 지속 교전에 증원으로 합류합니다.','3~5일 라운드, 실제 Person 전사/부상, C1 사기, C3 Deep Recovery 구조를 유지합니다.']],['UI·건설 진행',['활성 전쟁이 2개 이상이면 지도 상단 전쟁 배너를 드롭다운으로 표시합니다.','군사 탭에서 각 야전대의 전쟁·임무·목표·준비태세를 표시합니다.','건물 신축·업그레이드·도로·토지정비의 실제 공사 진행률을 지도 하단 Progress Bar로 표시합니다.']],['범위',['점령 소요시간, 공성전, 정식 동맹, 배상·영토할양, 해전, 병종·장군·전술은 D 범위 밖입니다.','C3F 수도우회·패퇴 중 점령 금지·전략도로 fallback과 C2 기술비는 유지합니다.']]]});
